export function createDecisionsStudio(store){
// The working tab and the selection are the shell's once bound; before that (a unit suite) they are this studio's.
let bridge=null,listeners=null,localTab='work',localSelected=null,formState,tipTimer;
const doc=()=>store.value?.document;
let project=doc();
const ui={stage:sectionFromAddress(3,'inputs'),comparisonView:'options',criterion:null,alternative:null,compare:[],node:null,question:null,filter:'gaps',sourceFocus:null,outputShown:50,proposal:null,busy:false,dirty:false,modal:null,step:0};
Object.defineProperties(ui,{
  tab:{get:()=>bridge?.state.tab||localTab,set:v=>{if(bridge)bridge.state.tab=v;else localTab=v}},
  selected:{get:()=>{const id=bridge?bridge.state.selected:localSelected;return id&&id!=='project'?id:null},set:v=>{if(bridge)bridge.state.selected=v||'project';else localSelected=v||null}},
  cursor:{get:()=>bridge?bridge.state.cursor!==false:true}
});
const sync=()=>{project=doc()||project};
// A decision is always in view while the chapter has one, as on the chapter's own page before.
const settle=()=>{sync();if(project)syncSelection()};
const decision=()=>(project?.decisions.records.find(d=>d.id===ui.selected)||project?.decisions.records.find(d=>d.id===ui.question)),option=()=>ui.proposal?.record||decision()?.alternatives.find(a=>a.id===ui.alternative)||chosen(decision())||decision()?.alternatives[0];
// The decision's state as a chip: the words are the domain's (statusLabel), the tone says how to read them.
const STATUS_TONE={accepted:'pass',recorded:'info',superseded:'reference',draft:'draft'};
const stateBadge=d=>`<span class="chip ${STATUS_TONE[d.status]||''}">${statusLabel(d)}</span>`,effect=v=>`<span class="d-effect ${esc(v?.effect||'unknown')}">${EFFECTS.find(e=>e[0]===v?.effect)?.[1]||'Needs evidence'}</span>`;
function toast(message){if(bridge)bridge.toast(message)}
// The shell draws the page; a change of tab pushes a history entry, anything else rewrites the current one.
function render(){sync();if(bridge)bridge.render(true)}
function syncSelection(){if(project.decisions.records.some(d=>d.id===ui.selected))ui.question=ui.selected;else if(!project.decisions.records.some(d=>d.id===ui.question))ui.question=project.decisions.records.find(d=>lensHolds(shellLens(),d))?.id||project.decisions.records[0]?.id||null;const d=decision();if(!d?.alternatives.some(a=>a.id===ui.alternative))ui.alternative=d?.selectedAlternativeId||d?.alternatives[0]?.id||null;if(!ui.compare.every(id=>d?.alternatives.some(a=>a.id===id))||ui.compare.length<Math.min(2,d?.alternatives.length||0))ui.compare=d?.alternatives.slice(0,2).map(a=>a.id)||[];}
async function send(type,payload={},message='Decision saved.'){
 if(ui.busy)return false;
 // A change to an existing record is reviewed inside the editor that proposed it, not in a second dialog stacked on it (U2-04).
 let command={type:type.includes('.')?type:'decision.'+type,payload};const editor=$('.d-dialog');if(editor?.open&&editor.querySelector('form')){command=await reviewChangeInDialog(editor,store.value?.document||project,command);if(!command)return false;}
 ui.busy=true;$('.d-dialog')?.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=true);
 try{const result=await store.command(command);project=result.document;if(result.selected)ui.selected=result.selected;ui.proposal=null;ui.node=null;syncSelection();ui.dirty=false;const opener=closeDialog(true,{restore:false});render();returnFocus(opener,{ids:[result.selected],attributes:['data-d-select','data-d-edit-option']});toast(message);
  // The decision just saved is brought into view and lit (U2-14).
  if(result.selected){const row=[...document.querySelectorAll('[data-d-select]')].find(e=>e.dataset.dSelect===result.selected);if(row)revealRecord(row.closest('article,li')||row)}
  return true}
 catch(e){const offline=looksOffline(e),el=$('#d-form-error')||$('#d-page-error');if(el){el.hidden=false;el.innerHTML=esc(e.message)+(e.conflict?' '+btn('refresh','Load latest project'):'')+(offline&&$('#d-form-error')?' '+btn('retry-submit','Try again','ux-retry'):'');el.scrollIntoView({block:'nearest'})}if(offline)markConnection('offline',{announce:toast});toast('Your input is preserved. Review the message and try again.');return false}
 finally{ui.busy=false;$('.d-dialog')?.querySelectorAll('button[type=submit]').forEach(b=>b.disabled=false)}
}
function questionPicker({create=true}={}){const d=decision();return `<div class="d-question-bar"><label><span>Design question</span><select id="d-question-select" title="${d?esc(d.id+' · '+d.question):''}">${project.decisions.records.filter(x=>x.id===d?.id||lensHolds(shellLens(),x)).map(x=>`<option value="${esc(x.id)}" title="${esc(x.id+' · '+x.question)}" ${d?.id===x.id?'selected':''}>${esc(x.id)} · ${esc(shortText(x.question,72))}</option>`).join('')||'<option>No decisions yet</option>'}</select></label>${create?btn('new-question',icon('plus')+'New question'):''}</div>`}
function recordActions(d){const missing=d.status==='draft'?recordChecklist(d).filter(c=>!c.ok):[];const transition=d.status==='draft'?btn('record','Record decision',missing.length?'':'primary',missing.length?'disabled aria-disabled="true" aria-describedby="d-record-reason"':''):d.status==='recorded'?btn('accept','Review architect acceptance','primary'):d.status==='accepted'?btn('model','Review model impact','primary'):'';return transition+btn('edit-question','Edit rationale & context',missing.length||!transition?'primary':'');}
function work(){
  const d=decision(),reviewed=project.decisions.intake?.sourceVersion===project.contentVersion&&project.decisions.intake?.qualityVersion===project.quality.version;
  const sections=[['inputs','Inputs & question'],['compare','Compare alternatives'],['record','Record & review']];
  const titles={inputs:'Frame the design question',compare:'Compare alternatives',record:'Record and review the decision'};
  const actions=!d?btn('new-question','Create a question','primary')+(ui.stage==='inputs'?btn('review-inputs',reviewed?'Inputs reviewed':'Mark inputs reviewed'):'')
    :ui.stage==='inputs'?btn('edit-question','Edit question & links','primary')+btn('review-inputs',reviewed?'Inputs reviewed':'Mark inputs reviewed')
    :ui.stage==='compare'?btn('new-alternative',icon('plus')+'Add alternative','primary')+btn('edit-question','Edit question & links'):recordActions(d);
  const context=questionPicker({create:!!d})+(d?`<div class="work-context-state"><span>${esc(d.id)} · Revision ${d.revision}</span>${stateBadge(d)}</div>`:'');
  return workFrameHTML({project:project,chapter:3,section:ui.stage,sections,title:titles[ui.stage],actions,context,body:ui.stage==='inputs'?inputs():ui.stage==='record'?record():comparison()});
}
function inputs(){
 const d=decision();
 const sourceNotice=ui.sourceFocus&&d?`<div class="r-reference-note" role="status">${ui.sourceFocus==='driver-assumptions'?'Review the unconfirmed linked drivers in Chapter 2 Work, then return to this comparison.':'Review the unconfirmed source requirements in Chapter 1 Work, then return to this comparison.'}</div>`:'';
 const sourceGroup=(title,rows,empty)=>`<section><h3>${title}</h3><div class="d-source-list">${rows.slice(0,4).join('')||'<p>'+empty+'</p>'}</div>${rows.length>4?`<details><summary>Show ${rows.length-4} more linked sources</summary><div class="d-source-list">${rows.slice(4).join('')}</div></details>`:''}</section>`;
 const requirements=d?.requirementIds.map(id=>{const a=project.artefacts.find(a=>a.id===id);return a?`<a data-work-record="${esc(id)}" href="${esc(projectURL('/?chapter=1&tab=work&section=requirement&artefact='+encodeURIComponent(id)))}" ${!a.confirmed?'data-d-source-warning="requirement"':''}><b>${esc(id)}</b><span>${esc(a.title)}</span><small>${a.confirmed?'Confirmed':'Unconfirmed · open in Chapter 1 Work'}</small></a>`:`<p class="r-error">Missing ${esc(id)}</p>`;})||[];
 const drivers=d?.driverIds.map(id=>{const c=criterion(project,d,id);return c?`<a data-work-record="${esc(id)}" href="${esc(projectURL('/?chapter=2&tab=work&section=scenarios&driver='+encodeURIComponent(id)))}" ${!c.confirmed?'data-d-source-warning="driver"':''}><b>${esc(c.code)} · ${esc(c.priority||'Priority not stated')}</b><span>${esc(c.title)}</span><small>${esc(c.kind==='quality'?'Quality target':'Architectural impact')}: ${esc(c.measure)} · ${c.confirmed?'Confirmed':c.kind==='quality'?'Target or driver unconfirmed · open Chapter 2 Work':'Driver unconfirmed · open Chapter 2 Work'}</small></a>`:`<p class="r-error">Missing ${esc(id)}</p>`;})||[];
 return `${d?`<div class="work-record-focus" data-work-record-focus="${esc(d.id)}"><span class="eyebrow">${esc(d.id)} · Design question</span><h3>${esc(d.question)}</h3><p>${esc(d.context)}</p><small class="d-origin">${esc(recordProvenance(project,d,3).label)} · ${esc(d.source)}</small></div>${sourceNotice}<div class="work-reading-columns">${sourceGroup('Required behaviour',requirements,'No requirements linked yet.')}${sourceGroup('Criteria for the choice',drivers,'No architectural drivers linked yet.')}</div>`:`<div class="r-empty"><h3>No design question yet.</h3><p>Frame a choice from the requirements and architectural drivers, then compare at least two alternatives.</p></div>${sourceNotice}`}<div class="r-reference-note">Reference comparisons are starting points. Numerical quality targets remain assumptions until confirmed against project evidence in Chapter 2.</div>`;
}
// The reading on the drivers (D-25-03 to D-25-06): each alternative's total, the range its unstated effects could move it
// to, and where it stands in the reading's own sentences (ruled out, dominated, the lead, tied, its rank), with how firmly
// the lead holds, the unstated effects that matter and the drivers left out. Arithmetic on the recorded effects only.
function readingHTML(d,S){const r=readDecision(project,d);if(!r||r.rows.length<2)return '';const title=id=>d.alternatives.find(a=>a.id===id)?.title||id,lines=readingLines(r,{alt:title}),of=r.rows.filter(x=>!x.out).length;
 const said=x=>lines.find(l=>['ruled-out','dominated'].includes(l.kind)&&l.id===x.id)?.text||(r.lead===x.id?(r.only?title(x.id)+' is the only alternative that meets the hard constraints.':title(x.id)+' leads on the drivers.'):r.tied.includes(x.id)?'Tied on the drivers.':x.rank?'Ranks '+x.rank+' of '+of+' on the drivers.':'');
 const hyp=suggestionHypothesis(S,r,title);
 return `<section class="d-reading" aria-label="The reading on the drivers"><h3>On the drivers</h3><ul>${r.rows.map(x=>`<li class="${x.out?'out':r.lead===x.id?'lead':''}"><b>${esc(x.id)} · ${esc(x.alt.title)}</b><span>${signed(x.score)}${x.low!==x.high?`, between ${signed(x.low)} and ${signed(x.high)} once the unstated effects are known`:''}</span><small>${esc(said(x))}</small></li>`).join('')}</ul>${lines.filter(l=>['firmness','unknowns','left-out','missing'].includes(l.kind)).map(l=>`<p class="d-said">${esc(l.text)}</p>`).join('')}${hyp?`<p class="d-said">${esc(hyp)}</p>`:''}<p class="r-note">${esc(READING_NOTE)}</p></section>`}
// An unstated effect's suggestions (D-25-08), each with its source, labelled and not counted. "Use this suggestion" opens
// the comparison editor filled with it; a conditional mark only asks its question.
function suggestionBlock(S,a,id){const c=S?.cells.find(x=>x.alternativeId===a.id&&x.driverId===id);return c?c.suggestions.map((s,i)=>`<div class="d-suggestion"><small>Suggestion · not counted</small><p>${s.ask?esc(s.reason):`Suggests <b>${esc(EFFECTS.find(e=>e[0]===s.effect)?.[1]||s.effect)}</b>: ${esc(s.reason)}`}</p><p class="d-evidence"><b>Source</b>${esc(s.evidence)}</p><button type="button" class="r-btn${s.ask?'':' gold'}" data-d-suggest="${esc(a.id)}" data-driver="${esc(id)}" data-index="${i}">${s.ask?'Answer it in the comparison':'Use this suggestion'}</button></div>`).join(''):''}
// A new project develops decisions and logical boundaries together. Explain the
// deliberate return loop instead of leaving an empty Impact picker or a circular handoff.
function responsibilityPrerequisite(){
 if(projectResponsibilities(project).length)return '';
 return `<section class="r-reference-note" data-decision-prerequisite aria-label="Logical responsibilities needed"><h3>Sketch the affected responsibilities first</h3><p>No logical responsibilities are recorded yet. You can compare and record a working choice now. Before architect acceptance, each alternative needs the logical responsibilities it would affect.</p><p>Open Chapter 4 to create provisional responsibilities from your requirements. Keep their assumptions explicit. Then use Back to return to this decision, open each alternative’s Impact step, link its affected responsibilities and review acceptance. Chapter 3 handoff follows acceptance; you can visit Chapter 4 before that handoff.</p><a class="r-btn" href="${esc(projectURL('/?chapter=4&tab=work&section=responsibilities'))}" data-decision-prerequisite-link>Define responsibilities in Chapter 4 ${icon('arrow')}</a></section>`;
}
function comparison(){const d=decision();if(!d)return empty();const pair=ui.compare.map(id=>d.alternatives.find(a=>a.id===id)).filter(Boolean),criterionId=d.driverIds.includes(ui.criterion)?ui.criterion:d.driverIds[0],S=ui.comparisonView==='evidence'?suggestEffects(project,d):null;
 return `${responsibilityPrerequisite()}<nav class="f-subview-tabs" aria-label="Decision comparison view">${[['options','Alternatives'],['evidence','Driver evidence']].map(([id,label])=>`<button type="button" class="r-btn" data-d-comparison-view="${esc(id)}" aria-pressed="${ui.comparisonView===id}">${label}</button>`).join('')}</nav>${d.alternatives.length>2?`<div class="l-form-grid">${[0,1].map(i=>`<label class="l-field"><span>${i?'Second':'First'} comparison option</span><select data-d-compare="${i}">${d.alternatives.map(a=>`<option value="${esc(a.id)}" ${ui.compare[i]===a.id?'selected':''}>${esc(a.id)} · ${esc(a.title)}</option>`).join('')}</select></label>`).join('')}</div>`:''}${ui.comparisonView==='options'?`<div class="d-options">${pair.map(a=>optionCard(d,a)).join('')}</div>`:`<p class="r-note">Each linked driver supplies a criterion; effects are explained with reasons and evidence. AIW shows the arithmetic on the drivers; it does not choose.</p>${readingHTML(d,S)}${d.driverIds.length?`<label class="f-criterion-picker"><span>Comparison criterion</span><select data-d-criterion>${d.driverIds.map(id=>{const c=criterion(project,d,id);return `<option value="${esc(id)}" ${criterionId===id?'selected':''}>${esc(id)} · ${esc(c?.title||'Missing driver')}</option>`}).join('')}</select></label>`:'<div class="r-reference-note">Link architectural drivers to define meaningful comparison criteria.</div>'}${[criterionId].filter(Boolean).map(id=>{const c=criterion(project,d,id);return c?`<section class="d-criterion"><header><span>${esc(c.id)} · ${esc(c.priority)}</span><h3>${esc(c.title)}</h3><p>${esc(c.measure)}</p><small>${c.kind==='quality'?(c.confirmed?'Confirmed quality target':'Unconfirmed quality target in Chapter 2'):(c.confirmed?'Reviewed driver':'Unconfirmed driver in Chapter 2')}</small></header><div class="d-assessments">${pair.map(a=>{const v=a.assessments[id];return `<article><small>${esc(a.id)} · ${esc(a.title)}</small>${effect(v)}<p>${esc(v?.reason||'Comparison reason missing.')}</p><p class="d-evidence"><b>Basis / evidence</b>${esc(v?.evidence||'Not recorded. This judgement needs support.')}</p>${(v?.effect||'unknown')==='unknown'?suggestionBlock(S,a,id):''}<button type="button" class="r-btn" data-d-edit-option="${esc(a.id)}" data-step="1">Edit comparison</button></article>`}).join('')}</div></section>`:''}).join('')}`}`;
}
function optionCard(d,a){return `<article class="d-option ${d.selectedAlternativeId===a.id?'chosen':''}" data-d-insight="alternative:${esc(a.id)}"><div class="d-option-meta"><span>${esc(a.id)}</span><span>${d.selectedAlternativeId===a.id?'Working choice':'Alternative'}</span></div><h3>${esc(a.title)}</h3><p>${esc(a.summary)}</p><details class="f-disclosure"><summary>Benefits and trade-offs</summary><dl><div><dt>Benefit</dt><dd>${esc(a.benefits||'Not recorded')}</dd></div><div><dt>Cost / trade-off</dt><dd>${esc(a.costs||'Not recorded')}</dd></div></dl></details><div class="r-actions"><button type="button" class="r-btn primary" data-d-preview="${esc(a.id)}">Preview impact → Model ${icon('arrow')}</button><button type="button" class="r-btn" data-d-edit-option="${esc(a.id)}">Edit</button></div><button type="button" class="d-choice-button" data-d-choose="${esc(a.id)}" ${d.selectedAlternativeId===a.id?'disabled':''}>${d.selectedAlternativeId===a.id?'✓ Current working choice':'Use as working choice'}</button></article>`}
// What recording needs, as the server checks it (decisions-domain.js): shown as a checklist, each item with
// the action that completes it; Record decision stays disabled, with the reason, until every item holds (U2-04).
function recordChecklist(d){const a=chosen(d),changed=decisionSourceChanged(project,d);return [
  {ok:d.alternatives.length>=2,label:'Compare at least two alternatives',detail:d.alternatives.length+' recorded',action:'go-compare'},
  {ok:!!a,label:'Choose a working alternative',detail:a?a.title:'No working choice yet · open Compare alternatives and use one as the working choice',action:'go-compare'},
  {ok:d.requirementIds.length>0&&d.driverIds.length>0,label:'Link requirements and architectural drivers',detail:d.requirementIds.length+' requirements · '+d.driverIds.length+' architectural drivers',action:'edit-links'},
  {ok:!!d.owner&&!!d.rationale,label:'Record the owner and rationale',detail:!d.owner&&!d.rationale?'Owner and rationale missing':!d.owner?'Owner missing':!d.rationale?'Rationale missing':'Recorded',action:'edit-rationale'},
  {ok:!changed,label:'Linked inputs are current',detail:changed?'A linked requirement or architectural driver changed since this decision was framed · review the links':'Current',action:'edit-links'}]}
function record(){const d=decision();if(!d)return empty();const a=chosen(d);const checks=d.status==='draft'?recordChecklist(d):[],missing=checks.filter(c=>!c.ok);return `${responsibilityPrerequisite()}<div class="d-state-path"><span class="${a?'done':''}">1 · Working choice</span><span class="${['recorded','accepted'].includes(d.status)?'done':''}">2 · Recorded decision</span><span class="${d.status==='accepted'?'done':''}">3 · Architect accepted</span></div><div class="d-record-choice"><small>Preferred alternative</small><h3>${a?esc(a.title):'No working choice yet'}</h3><p>${esc(d.rationale||'Explain why this choice best addresses the linked requirements and architectural drivers, and why the alternatives were not selected.')}</p></div>${d.status==='draft'?`<section class="d-checklist" aria-labelledby="d-checklist-title"><h3 id="d-checklist-title">Before this decision can be recorded</h3><ol>${checks.map(c=>`<li class="${c.ok?'done':'open'}"><span aria-hidden="true">${c.ok?'✓':'○'}</span><div><b>${esc(c.label)}</b><small>${esc(c.detail)}</small></div>${c.ok?'':btn(c.action,c.action==='go-compare'?'Open Compare alternatives':c.action==='edit-links'?'Edit links':'Edit rationale')}</li>`).join('')}</ol></section>`:''}${d.status==='draft'&&missing.length?`<p id="d-record-reason" class="d-record-reason">Record decision needs: ${esc(missing.map(c=>c.label.toLowerCase()).join(', '))}.</p>`:d.status==='draft'?'<p id="d-record-reason" class="d-record-reason ok">Every precondition holds. Recording marks the working choice as the decision; architect acceptance and governance remain separate steps.</p>':''}<details class="f-disclosure"><summary>${d.assumptionsResolved?'Assumptions and risk treatment':'Open assumptions and risk treatment'}</summary><dl class="d-record-details"><div><dt>Assumptions</dt><dd>${esc(d.assumptions||'None recorded')}<small>${d.assumptionsResolved?'Confirmed: '+esc(d.assumptionEvidence):'Open assumptions'}</small></dd></div><div><dt>Risks</dt><dd>${esc(d.risks||'None recorded')}</dd></div><div><dt>Treatment</dt><dd>${esc(d.mitigation||'Not recorded')}</dd></div><div><dt>Owner / source</dt><dd>${esc(d.owner)} · ${esc(d.source)}</dd></div></dl></details><details class="f-disclosure"><summary>Governance · ${governanceLabel(d,project)}</summary><section class="d-governance"><p class="r-kicker">Separate review / Governance</p><h3>${governanceLabel(d,project)}</h3><p>Architect acceptance records the design choice. Governance approval requires a separate review outcome and supporting evidence.</p>${d.governance?`<p>${esc(d.governance.reviewer)} · ${esc(d.governance.evidence)}</p>`:''}${btn('governance','Record governance review')}${btn('supersede','Supersede decision')}</section></details><details class="f-disclosure"><summary>Recorded revisions · ${d.history.length}</summary>${revisionHistory(d)}</details><details class="f-disclosure"><summary>Decision conflicts · ${project.decisions.conflicts.length}</summary>${conflicts()}${btn('new-conflict','Record a conflict')}</details>`}
function revisionHistory(d){return [...d.history].reverse().map(h=>`<details class="d-history"><summary><span>r${h.revision} · ${esc(h.event)}</span><small>${new Date(h.at).toLocaleDateString('en-GB')}</small></summary><p>${esc(h.alternative||'No alternative selected')}</p><p>${esc(h.rationale||'No rationale recorded')}</p><small>${esc(h.requirementIds.join(', '))} · ${esc(h.driverIds.join(', '))}</small></details>`).join('')||'<p class="r-note">Recording and acceptance preserve the choice and rationale. A later edit creates a working revision and makes earlier model impacts inactive.</p>'}
function conflicts(){return project.decisions.conflicts.map(c=>`<article class="d-conflict"><small>${esc(c.id)} · ${esc(c.decisionIds.join(' / '))}</small><h3>${esc(c.title)}</h3><p>${conflictResolved(project,c)?'Resolved':c.status==='resolved'?'Changed decision — review resolution':'Open conflict'}${c.resolution?' · '+esc(c.resolution):''}</p><button type="button" class="r-btn" data-d-conflict="${esc(c.id)}">Review conflict</button></article>`).join('')||'<p class="r-note">No conflicts recorded.</p>'}
function contextRecord(key){const [kind,id]=key.split(':');return kind==='alternative'?(ui.proposal?.record.id===id?ui.proposal.record:decision()?.alternatives.find(a=>a.id===id)||option()):kind==='driver'?project.quality.drivers.find(q=>q.id===id):kind==='responsibility'?projectResponsibilities(project).find(r=>r.id===id):project.artefacts.find(r=>r.id===id);}
// The details of the record in view, then the one lifecycle path (round 12, GR-GOV-23): retire it, restore what left.
function inspector(){const d=decision();return inspectorBody()+(ui.node&&!ui.node.startsWith('alternative:')?'':lifecycleHTML(project,3,d?.id,'data-d-action'));}
function inspectorBody(){const d=decision(),a=option(),g=decisionGuidance(project,d,a,ui.tab);if(d&&!ui.node&&!ui.proposal)return decisionOverview(d);if(ui.node&&!ui.node.startsWith('alternative:'))return contextInspector(ui.node);return `<header class="r-inspector-head"><span>${icon('cursor')}Details</span></header><div class="r-inspector-body">${btn('back','Back to workspace','r-mobile-return')}${d?`<p class="r-kicker">${esc(d.id)} / Revision ${d.revision}</p>${stateBadge(d)}<h2>${a?esc(a.title):'Explore an alternative'}</h2>${a?`<p class="d-preview-label">${ui.proposal?'Unsaved draft suggestion':d.selectedAlternativeId===a.id?'Current working choice':'Alternative preview'}</p><p>${esc(a.summary)}</p><h3>Consequences</h3><p>${esc(a.consequences||'Not described yet')}</p><h3>Architectural approach</h3><p>${esc(a.pattern||'Not recorded')}</p><h3>Anti-pattern to avoid</h3><p>${esc(a.antiPattern||'Explore a failure boundary in Co-design.')}</p><div class="r-actions">${ui.proposal?btn('edit-proposal','Review & edit proposal','gold'):`<button type="button" class="r-btn" data-d-edit-option="${esc(a.id)}">Edit alternative</button>`}</div><h3>Driver implications</h3><div class="d-lens-drivers">${d.driverIds.map(id=>{const c=criterion(project,d,id);return c?`<button type="button" data-d-node="driver:${esc(id)}"><b>${esc(id)} · ${esc(c.title)}</b>${effect(a.assessments[id])}<small>${esc(c.measure)}</small></button>`:''}).join('')}</div><h3>Affected responsibilities</h3><div class="d-source-list">${a.responsibilityIds.map(id=>`<a href="/?chapter=4&object=${esc(id)}">${esc(projectResponsibilities(project).find(r=>r.id===id)?.title||id)} ${icon('arrow')}</a>`).join('')}</div>`:''}${decisionSourceChanged(project,d)?'<div class="r-error">Inputs changed. Revise the comparison before accepting or applying this decision.</div>':''}<h3>Governance</h3><p>${governanceLabel(d,project)}</p>`:'<h2>Frame a choice with consequences.</h2>'}${evidenceContextHTML(project,d?.id,ui.tab)}<div class="r-attention"><p class="r-kicker">A useful next thought</p><p>${esc(g.attention)}</p><small>${esc(g.next)}</small>${btn('mind',icon('spark')+'Explore a draft suggestion','gold')}</div></div>`}
function decisionOverview(d){return '<div class="r-inspector-body"><h3>Design question</h3><p>'+esc(d.question)+'</p>'+stateBadge(d)+'<p>'+esc(d.context||'Context not recorded.')+'</p><h3>Alternatives compared</h3>'+d.alternatives.map(a=>'<section class="decision-card-option"><h4>'+esc(a.title)+'</h4><span class="chip">'+(d.selectedAlternativeId===a.id?'Working choice':a.rejectionReason?'Rejected with rationale':'Alternative · not selected')+'</span><p>'+esc(a.summary||'Summary not recorded.')+'</p>'+(a.rejectionReason?'<p>Rejection rationale: '+esc(a.rejectionReason)+'</p>':'')+'<button type="button" class="btn" data-d-edit-option="'+esc(a.id)+'">Review alternative</button></section>').join('')+'<h3>Why this choice?</h3><p>'+esc(d.rationale||'Architect rationale not recorded.')+'</p><p>'+esc(d.assumptions||'No assumptions recorded.')+'</p><div class="r-actions">'+btn('edit-question','Edit question and rationale')+btn('go-compare','Compare alternatives → Work')+'</div>'+evidenceContextHTML(project,d.id,ui.tab)+'</div>';}
function contextInspector(key){const c=contextRecord(key),d=decision(),a=option(),[kind,id]=key.split(':');if(!c)return '';const q=kind==='driver'?criterion(project,d,id):null;return `<header class="r-inspector-head"><span>${icon('cursor')}Details</span></header><div class="r-inspector-body">${btn('back','Back to workspace','r-mobile-return')}<p class="r-kicker">${esc(kind)} / ${esc(id)}</p><h2>${esc(c.title)}</h2><p>${esc(q?q.measure:c.description)}</p>${q?`${effect(a?.assessments[id])}<p>${esc(a?.assessments[id]?.reason||'Comparison not recorded.')}</p><h3>Evidence / basis</h3><p>${esc(a?.assessments[id]?.evidence||'This judgement needs supporting evidence.')}</p>`:`<h3>Decision consequence</h3><p>${esc(a?.consequences||d.context)}</p>`}<p>${esc(d.id)} · ${esc(d.question)}</p><div class="r-actions">${btn('inspect-alternative','Return to alternative')}<a class="r-btn" href="${kind==='driver'?projectURL('/?chapter=2&tab=work&driver='+encodeURIComponent(id)):kind==='responsibility'?'/?chapter=4&object='+id:'/?chapter=1&tab=work&artefact='+id}">Open source ${icon('arrow')}</a></div><div class="r-attention"><p>Review the effects across all alternatives when this input changes.</p>${btn('sol','Act with Sol')}</div></div>`}
function validation(){return validationSurfaceHTML(project,3,{title:'Can the choice be explained?',purpose:'Review alternatives, rationale, comparison evidence, source links and unresolved assumptions.',run:btn('run-checks','Run checks','primary'),findings:decisionFindings(project).map(f=>({...f,objectId:f.decisionId,reference:f.decisionId,actions:'<button type="button" class="btn" data-d-fix="'+esc(f.id)+'">Open remedy</button>'}))});}
function output(){const ds=project.decisions.records,active=decision(),destination=(chapter,rs)=>{const matches=rs.filter(r=>active&&r.decisionIds?.includes(active.id));return projectURL('/?chapter='+chapter+'&tab=work'+(matches.length===1?'&object='+encodeURIComponent(matches[0].id):''));};return outputWorkspaceHTML(project,3,{title:'A reasoned basis for the application model',summary:ds.length+' decisions · '+ds.filter(d=>decisionCurrent(project,d)).length+' current architect-accepted · '+ds.filter(d=>impactCurrent(project,d)).length+' applied impacts',handoff:'<h3>Carry the decision and its reasoning together</h3><p>Accepted decisions appear on affected responsibilities and their physical implementations. Only explicitly applied, current impacts add relationships to the model.</p><p>'+esc(decisionHandoffCurrent(project)?'Current handoff recorded':'Working decisions · handoff needs review')+'</p>'+btn('handoff','Review & carry forward','gold')+'<div class="r-actions"><a class="btn" href="'+esc(destination(4,project.logical.responsibilities))+'">Open logical application</a><a class="btn" href="'+esc(destination(5,project.realisation.components))+'">Open Application realization</a></div>'});}
function empty(){return `<div class="r-empty"><h3>No design question yet.</h3><p>Link its requirements and architectural drivers, then compare alternatives.</p></div>`}
// One editor at a time, in the shell's dialog host; closing it returns focus to what opened it, found again after the
// page is redrawn (dialog.js rememberOpener / returnFocus).
function dialog(title,body,kind){if(presentAssistant(kind,title,body))return;hideTip();const open=$('.d-dialog'),opener=open?open.opener:rememberOpener(document.activeElement);if(open)closeSharedDialog(open,{restoreFocus:false});ui.modal=kind;ui.dirty=false;const el=openDialog({className:'dialog l-dialog r-dialog d-dialog',labelledBy:'d-dialog-title',opener,html:`<header><div><span class="eyebrow">Chapter 03 / ${esc(ui.tab)}</span><h2 id="d-dialog-title">${title}</h2></div>${dbtn('close',icon('close'),'icon-only','aria-label="Close dialog"')}</header><div id="d-form-error" class="l-error" role="alert" hidden></div>${body}<div class="l-discard d-discard" id="d-discard" hidden><p>Discard your unsaved changes?</p>${dbtn('keep','Keep editing')}${dbtn('discard','Discard changes')}</div>`,onCancel:()=>closeDialog(),closeSelector:null});refineAssistantDialog(el,kind);}
function closeDialog(force=false,{restore=true}={}){if(ui.busy&&!force)return null;if(ui.dirty&&!force){$('#d-discard').hidden=false;$('#d-discard').scrollIntoView({block:'nearest'});$('#d-discard button').focus();return null}const el=$('.d-dialog'),opener=el?.opener||null;ui.modal=null;ui.dirty=false;if(el)closeSharedDialog(el,{restoreFocus:restore});return opener}
function steps(names){return `<nav class="l-steps" aria-label="Editing steps">${names.map((t,i)=>`<button type="button" class="btn${ui.step===i?' active':''}" data-d-step="${i}" aria-pressed="${ui.step===i}">${t}</button>`).join('')}</nav>`}
function step(i,{check=false}={}){if(check&&!canLeaveStep($('.d-dialog form'),'data-d-panel',i))return;ui.step=Math.min(2,Math.max(0,i));document.querySelectorAll('[data-d-panel]').forEach(el=>el.hidden=Number(el.dataset.dPanel)!==ui.step);document.querySelectorAll('[data-d-step]').forEach(el=>{const on=Number(el.dataset.dStep)===ui.step;el.setAttribute('aria-pressed',String(on));el.classList.toggle('active',on)});$('.d-dialog').scrollTop=0;const panel=$('[data-d-panel="'+ui.step+'"]');panel?.querySelector('input,select,textarea')?.focus({preventScroll:true})}
function editQuestion(isNew=false,initialStep=0,preset=null){sync();const d=isNew?{topic:'custom',category:'',question:'',context:'',requirementIds:[],requirementGroupIds:[],driverIds:[],stakeholderIds:[],dependsOn:[],rationale:'',assumptions:'',assumptionEvidence:'',assumptionsResolved:false,risks:'',mitigation:'',owner:'',source:'',...(preset||{})}:decision();if(!d)return;const people=project.artefacts.filter(a=>a.type==='stakeholder'||a.type==='actor');formState={id:d.id};ui.step=initialStep;dialog(isNew?'Frame a design question':'Revise '+d.id,`<form id="d-question-form">${steps(['Question','Traceability','Reasoning'])}<section data-d-panel="0"><div class="l-form-grid">${fSave('topic',d.topic,{options:decisionTopics(project)})}${fSave('category',d.category||'',{options:[['','Not stated'],...DECISION_CATEGORIES.map(c=>[c.id,c.name])]})}${fSave('owner',d.owner)}</div>${fSave('question',d.question)}${fSave('context',d.context)}${fSave('source',d.source)}${dbtn('next-step','Next: traceability '+icon('arrow'))}</section><section data-d-panel="1" hidden>${fSave('requirementIds',d.requirementIds,{options:project.artefacts.filter(a=>a.type==='requirement').map(r=>({id:r.id,strong:r.id,title:r.title,note:r.confirmed?'Confirmed':'Unconfirmed source'}))})}${fSave('requirementGroupIds',d.requirementGroupIds||[],{options:requirementGroups(project).map(g=>({id:g.id,strong:g.id,title:g.title,note:kindName(g.kind)})),empty:'No requirement group yet.'})}${fSave('driverIds',d.driverIds,{options:project.quality.drivers.map(q=>({id:q.id,strong:driverCode(project,q),title:q.title,note:(driverPriority(q)||'Priority not stated')+' · '+(q.kind==='quality'||!q.kind?(q.targetConfirmed?'Target confirmed':'Target assumption'):(q.confirmed?'Driver reviewed':'Driver unconfirmed'))}))})}${fSave('assumptionIds',d.assumptionIds||[])}${fSave('stakeholderIds',d.stakeholderIds||[],{options:people.map(a=>({id:a.id,strong:a.id,title:a.title})),empty:'Add stakeholders or actors in Chapter 1 first.'})}${fSave('stakeholderNote',d.stakeholderNote||'')}${fSave('dependsOn',d.dependsOn||[],{options:project.decisions.records.filter(x=>x.id!==d.id).map(x=>({id:x.id,strong:x.id,title:x.question})),empty:'No other decision yet.'})}${fSave('dependencies',d.dependencies||'')}${dbtn('next-step','Next: reasoning '+icon('arrow'))}</section><section data-d-panel="2" hidden>${fSave('rationale',d.rationale)}${fSave('assumptions',d.assumptions)}${fSave('assumptionEvidence',d.assumptionEvidence)}${fSave('assumptionsResolved',d.assumptionsResolved)}${fSave('risks',d.risks)}${fSave('mitigation',d.mitigation)}${fSave('impact',d.impact||'')}<div class="l-form-grid">${fSave('licensing',d.licensing||'')}${fSave('skills',d.skills||'')}</div>${fSave('documentation',d.documentation||'')}</section><p class="d-edit-note">${d.id?'Saving creates a working revision. Earlier acceptance, governance evidence, and applied model impacts require review. The ID '+d.id+' remains unchanged.':'A stable ADR reference is assigned on save. Add at least two alternatives to compare.'}</p><div class="l-dialog-actions">${dbtn('close','Cancel')}<button type="submit" class="btn primary">Save working revision</button></div></form>`,'question');step(initialStep)}
function newOption(){const d=decision();return {title:'',summary:'',benefits:'',costs:'',consequences:'',pattern:'',antiPattern:'',rejectionReason:'',source:'',componentIds:[],responsibilityIds:[],relationships:[],assessments:Object.fromEntries(d.driverIds.map(id=>[id,{effect:'unknown',reason:'',evidence:''}]))};}
// prefill: a suggested effect (D-25-08) the person chose to use, filled into its driver's fieldset for them to review; it
// is recorded only when they save, through decision.alternative, and what they save carries no drafted mark. "Breaks it"
// is offered only for a constraint driver (D-25-03), or where it is already recorded, so a save shows the refusal.
function editAlternative(id=null,initialStep=0,proposal=null,prefill=null){sync();const d=decision(),a=proposal?.record||d.alternatives.find(a=>a.id===id)||newOption(),pre=prefill&&!prefill.ask?{effect:prefill.effect,reason:prefill.reason,evidence:prefill.evidence}:null;formState={id:d.id,alternativeId:proposal?proposal.existingId:id};ui.step=initialStep;dialog(proposal?'Review & edit the alternative proposal':id?'Revise '+id:'Add an alternative',`<form id="d-alternative-form">${steps(['Approach','Comparison','Impact'])}<section data-d-panel="0">${fAlternative('title',a.title)}${fAlternative('summary',a.summary)}<div class="l-form-grid">${fAlternative('benefits',a.benefits)}${fAlternative('costs',a.costs)}</div>${fAlternative('consequences',a.consequences)}${fAlternative('pattern',a.pattern)}${fAlternative('antiPattern',a.antiPattern)}${fAlternative('rejectionReason',a.rejectionReason||'')}${fAlternative('source',a.source||'')}${dbtn('next-step','Next: comparison '+icon('arrow'))}</section><section data-d-panel="1" hidden><div class="r-reference-note">Describe the expected effect on each architectural driver, why, and the evidence or explicit analytical basis. These judgements explain expected effects. Quality targets still need measured evidence.</div>${d.driverIds.map(id=>{const c=criterion(project,d,id),mine=prefill?.driverId===id,v=(mine&&pre)||a.assessments[id]||{};return c?`<fieldset class="d-criterion-editor${mine?' d-suggested':''}"><legend>${esc(id)} · ${esc(c.title)}</legend><p>${esc(c.measure)} · ${c.kind==='quality'?(c.confirmed?'confirmed quality target':'unconfirmed quality target'):(c.confirmed?'reviewed driver':'unconfirmed driver')}</p>${mine?`<p class="d-suggestion" role="note"><small>${prefill.ask?'A question from the SA Playbook':'Filled from a suggestion'}</small>${esc(prefill.ask?prefill.reason:'Source: '+prefill.evidence+'.')} Nothing is recorded until you save; what you save is your own judgement.</p>`:''}${fAlternative('effect',v.effect,{item:id,label:'Effect on '+id,options:c.kind==='constraint'||v.effect==='violates'?EFFECTS:EFFECTS.filter(e=>e[0]!=='violates')})}${fAlternative('reason',v.reason,{item:id,label:'Reason for '+id})}${fAlternative('evidence',v.evidence,{item:id,label:'Evidence / analytical basis for '+id})}</fieldset>`:''}).join('')||'<p>Link architectural drivers to the design question first.</p>'}${dbtn('next-step','Next: model impact '+icon('arrow'))}</section><section data-d-panel="2" hidden>${responsibilityPrerequisite()}${fAlternative('responsibilityIds',a.responsibilityIds,{options:projectResponsibilities(project).map(r=>({id:r.id,title:r.title}))})}${fAlternative('componentIds',a.componentIds||[],{options:(project.realisation?.components||[]).map(c=>({id:c.id,strong:c.ref,title:c.title})),empty:'No application component yet.'})}<h3>Proposed relationships</h3><p>Describe the responsibility relationship this option would add. The existing reference model remains visible for comparison.</p><div id="d-relationship-rows">${relationshipRows(a.relationships)}</div>${dbtn('add-relationship','Add proposed relationship')}<p class="r-note">Selecting an endpoint also selects its responsibility. Every relationship stays a draft suggestion until the decision is accepted and its impact explicitly applied.</p></section><p class="d-edit-note">Saving revises ${esc(d.id)}. Review the working choice again before acceptance.</p><div class="l-dialog-actions">${dbtn('close','Cancel')}<button type="submit" class="btn primary">${proposal?'Save edited proposal':'Save alternative'}</button></div></form>`,'alternative');step(initialStep);if(prefill){ui.dirty=!!pre;$('.d-dialog [name="effect:'+prefill.driverId+'"]')?.focus({preventScroll:true})}}
// A suggested effect, read again from the saved project (never taken from the page), fills the comparison editor at its
// driver; nothing is recorded until the person saves it there.
function useSuggestion(altId,driverId,i=0){sync();const d=decision(),s=d&&suggestEffects(project,d)?.cells.find(c=>c.alternativeId===altId&&c.driverId===driverId)?.suggestions[i];if(!s){toast('That suggestion no longer applies to the saved comparison.');return}editAlternative(altId,1,null,{driverId,...s})}
function relationshipRows(rows){return rows.map((e,i)=>`<div class="d-relationship-row" data-rel-row="${i}"><div class="l-form-grid">${['from','to'].map(key=>fAlternative('rel-'+key,e[key],{item:i,label:(key==='from'?'From':'To')+' responsibility '+(i+1),options:[['','Choose responsibility'],...projectResponsibilities(project).map(r=>[r.id,r.title])],extra:'data-rel-endpoint'})).join('')}</div>${fAlternative('rel-label',e.label,{item:i,label:'Relationship meaning '+(i+1)})}<button type="button" class="btn" data-d-remove-rel="${i}">Remove relationship ${i+1}</button></div>`).join('')}
function collectRelationships(){const form=$('#d-alternative-form');return [...form.querySelectorAll('[data-rel-row]')].map(el=>{const i=el.dataset.relRow;return {from:form.elements['rel-from-'+i].value,to:form.elements['rel-to-'+i].value,label:form.elements['rel-label-'+i].value}})}
function showAcceptance(){sync();const d=decision(),fs=decisionFindings(project).filter(f=>f.decisionId===d.id),gaps=fs.filter(f=>f.level==='error');dialog('Architect acceptance · '+d.id,`<form id="d-accept-form">${responsibilityPrerequisite()}<p><b>${esc(chosen(d)?.title||'No choice selected')}</b></p><p>${esc(d.rationale||'Rationale is missing.')}</p><div class="r-reference-note">${gaps.length} content or conflict gaps · ${fs.length-gaps.length} assumptions and review items. This records architect acceptance; governance approval remains separate.</div>${gaps.length?`<p>Resolve the content and conflict gaps before accepting this decision.</p>${dbtn('validate','Review findings','primary')}`:`${fs.length?checkHTML('acknowledge','I acknowledge the open assumptions and review items.',{required:true}):''}<div class="l-dialog-actions">${dbtn('close','Cancel')}<button type="submit" class="btn primary">Accept architecture decision</button></div>`}</form>`,'accept')}
function showApply(){sync();const d=decision(),a=option();if(!a)return;const current=a.id===d.selectedAlternativeId&&decisionCurrent(project,d);formState={id:d.id,alternativeId:a.id,revision:d.revision};dialog('Review model changes · '+d.id,`<form id="d-apply-form"><p>${esc(a.title)}</p><div class="d-before-after"><div><small>Current reference</small><p>${referenceEdges.filter(e=>a.responsibilityIds.includes(e.from)&&a.responsibilityIds.includes(e.to)).map(e=>esc(e.from+' → '+e.to+': '+e.label)).join('<br>')||'No direct relationship within these selected responsibilities.'}</p></div><div><small>Proposed additions</small>${a.relationships.map(e=>`<p>${esc(e.from+' → '+e.to)}<br><b>${esc(e.label)}</b></p>`).join('')||'<p>No relationships described.</p>'}</div></div><p>Applying adds traced relationships for this decision to the application model. Physical implementations inherit the decision reference through their logical responsibility.</p>${!current?`<div class="r-reference-note">Choose, record, and accept this alternative before applying its impact.</div>${dbtn('record-view','Open decision record','primary')}`:`${checkHTML('reviewed','I have reviewed these proposed relationships and their consequences.',{required:true})}<div class="l-dialog-actions">${dbtn('close','Cancel')}<button type="submit" class="btn primary">Apply reviewed model changes</button></div>`}</form>`,'apply')}
function showGovernance(){sync();const d=decision();dialog('Record governance evidence · '+d.id,`<form id="d-governance-form"><p>Record the outcome of a separate governance review. This form does not perform that review or automatically approve the architecture.</p>${recordField('decision.governance','status',d.governance?.status||'pending')}${recordField('decision.governance','reviewer',d.governance?.reviewer||'')}${recordField('decision.governance','evidence',d.governance?.evidence||'')}<p class="r-note">The evidence applies to ${esc(d.id)} revision ${d.revision}. A later revision requires review.</p><div class="l-dialog-actions">${dbtn('close','Cancel')}<button type="submit" class="btn primary">Save governance evidence</button></div></form>`,'governance')}
function editConflict(id=null,pair=null){sync();const c=project.decisions.conflicts.find(c=>c.id===id)||{decisionIds:pair||[ui.selected,project.decisions.records.find(d=>d.id!==ui.selected)?.id],title:'',resolution:'',owner:'',status:'open'};formState={conflictId:c.id};dialog(c.id?'Review '+c.id:'Record a decision conflict',`<form id="d-conflict-form"><div class="l-form-grid">${[0,1].map(i=>fConflict('decision'+i,c.decisionIds[i],{options:project.decisions.records.map(d=>[d.id,d.id+' · '+d.question])})).join('')}</div>${fConflict('title',c.title)}${fConflict('resolution',c.resolution)}${fConflict('owner',c.owner)}${fConflict('status',c.id&&conflictResolved(project,c)?'resolved':'open')}<div class="l-dialog-actions">${dbtn('close','Cancel')}<button type="submit" class="btn primary">Save conflict review</button></div></form>`,'conflict')}
function handoff(){const accepted=project.decisions.records.filter(d=>decisionCurrent(project,d)),fs=decisionFindings(project);dialog('Carry decisions into Chapters 4 and 5',`<form id="d-handoff-form"><p class="l-note">Acknowledging records the handoff with the open findings; it does not resolve them or approve the design.</p><p>${accepted.length} current architect-accepted decisions will carry their original ADR references, requirements, drivers, and rationale.</p><div class="r-reference-note">${fs.length} open findings travel with the project. Approval status remains explicit.</div>${!decisionReviewCurrent(project)?`<p>Run checks against the current revisions first.</p><button type="button" class="btn primary" disabled title="Resolve the prerequisite above first">Carry forward</button>${dbtn('validate','Go to validation','primary')}`:!accepted.length?`<p>Accept at least one decision before handoff.</p><button type="button" class="btn primary" disabled title="Resolve the prerequisite above first">Carry forward</button>${dbtn('record-view','Review decision record','primary')}`:`${fs.length?checkHTML('acknowledge','I acknowledge the open findings that travel with these decisions.',{required:true}):''}<div class="l-dialog-actions">${dbtn('close','Cancel')}<button type="submit" class="btn primary">Carry forward & open Chapter 4</button></div>`}</form>`,'handoff')}
function assistant(kind){const d=decision(),a=option(),g=decisionGuidance(project,d,a,ui.tab),context=ui.node?contextRecord(ui.node):null;if(kind==='mind'){if(!d){dialog('Co-design · Explore a design question','<p>Capture the choice you need to make, then compare its possible approaches and consequences.</p>'+btn('new-question','Frame a design question','primary'),'mind');return}dialog('Co-design · Explore the design space',`${evidenceAssistantLink('mind')}<p>${esc(d.id)} / ${esc(ui.tab)} · ${esc(d.question)}</p><div class="r-reference-note">${{work:'Which approach best addresses the linked architectural drivers, and what would it cost?',model:'Which responsibility or relationship would change if this approach were adopted?',validate:'Which failure boundary would invalidate the reasoning or expose an unsupported assumption?',output:'Which consequences and tests must follow this decision into the application model?'}[ui.tab]}</div>${decisionPatterns(d).map(p=>`<article class="d-pattern"><small>${esc(p.kind)}</small><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><p><b>Watch for:</b> ${esc(p.antiPattern)}</p><button type="button" class="r-btn gold" data-d-pattern="${esc(p.id)}">Preview an editable draft suggestion</button></article>`).join('')}<p class="r-note">Contextual proposals use project rules. Live-generation status is shown in Sol.</p>`,'mind');return}const actionMap={work:`${btn('edit-question','Edit decision context')}${btn('compare-view','Compare alternatives')}${ui.proposal?btn('edit-proposal','Review & edit proposal'):a?`<button type="button" class="r-btn" data-d-edit-option="${esc(a.id)}" data-step="1">Edit comparison evidence</button>`:''}${btn('record-view','Open decision record')}`,model:`${ui.proposal?btn('edit-proposal','Review & edit proposal'):a?`<button type="button" class="r-btn" data-d-edit-option="${esc(a.id)}" data-step="2">Edit proposed impact</button>`:''}${btn('apply-impact','Review model changes')}`,validate:`${btn('run-checks','Run current checks','primary')}${btn('record-view','Review the decision')}`,output:`${btn('export-md','Export decision register')}${btn('handoff','Review handoff','gold')}${btn('governance','Record governance review')}`};dialog('Chapter tools · Act on this decision',`${evidenceAssistantLink('sol')}<p>${d?esc(d.id):'Project'} / ${esc(ui.tab)} · ${esc(context?.title||a?.title||d?.question||'Decision context')}</p><div class="r-reference-note">${esc(g.next)}</div><p>${esc(g.attention)}</p><div class="r-menu-actions">${d?actionMap[ui.tab]:btn('new-question','Create a design question','primary')}</div>`,'sol')}
function previewPattern(id){const pattern=decisionPatterns(decision()).find(p=>p.id===id);if(!pattern)return;const proposal=proposedAlternative(project,decision(),pattern);if(proposal.existingId)proposal.record.consequences+=' Verify this approach under a repeated request and a partial dependency failure.';closeDialog(true);ui.proposal=proposal;ui.node=null;navigate('model');toast('Unsaved alternative preview. Review and edit before saving.')}
function selectDecision(id,stage=null){if(!project.decisions.records.some(d=>d.id===id))return;ui.selected=id;ui.alternative=null;ui.compare=[];ui.proposal=null;ui.node=null;ui.sourceFocus=null;syncSelection();if(stage){ui.tab='work';ui.stage=stage}render();window.dispatchEvent(new CustomEvent('aiw:inspect-details'))}
function navigate(tab,stage=null){if(ui.modal)closeDialog(true);if(stage)ui.stage=stage;ui.node=null;if(bridge)bridge.setTab(tab);else ui.tab=tab;$('.tabs [aria-selected="true"]')?.focus({preventScroll:true});$('#workspace .stage')?.scrollIntoView({block:'start'})}
// Carrying the decisions forward opens Chapter 4 in place, on its Work tab.
// The shell always binds its bridge (entry.js, app.js), so the next chapter opens in place; there is no page without it.
function goChapter(n){if(!bridge)return;bridge.setChapter(n,{tab:'work'})}
// The model impact of the selected decision is reviewed and applied in its own dialog, from wherever it is asked for.
function reviewImpact(){ui.alternative=decision()?.selectedAlternativeId||ui.alternative;ui.proposal=null;showApply()}
function next(id=null){const m=decisionMilestones(project).find(m=>m.id===id)||decisionMilestones(project).find(m=>!m.done);if(!m){goChapter(4);return}if(m.id==='impact'){const due=project.decisions.records.find(d=>decisionCurrent(project,d)&&!impactCurrent(project,d));if(due){ui.selected=due.id;syncSelection()}navigate('work','record');reviewImpact();return}navigate(m.tab,m.stage||null)}
function selectNode(key){ui.node=key.startsWith('alternative:')?null:key;hideTip();const lens=$('#inspector');if(lens){lens.innerHTML=inspector();window.dispatchEvent(new CustomEvent('aiw:inspect-details'));}}
// The chapter's files are offered by the Output tab's documents list (output-documents.js); the Sol menu's export goes
// through the same mechanic (round 26, D-26-13).
async function download(markdown=false){try{const file=await downloadOutput('/api/export?chapter=3&format='+(markdown?'md':'json'),{chapter:3});toast('Downloaded '+file.filename+'.')}catch(e){toast(e.message)}}
function fix(id){const f=decisionFindings(project).find(f=>f.id===id);if(!f)return;if(f.code==='intake'){navigate('work','inputs');return}if(f.code==='empty'){editQuestion(true);return}ui.selected=f.code==='cited-not-linked'?f.items?.[0]?.objectId||ui.selected:f.decisionId;ui.node=null;ui.proposal=null;syncSelection();render();if(f.conflictId)return editConflict(f.conflictId);if(f.pair)return editConflict(null,f.pair);if(f.alternativeId)return editAlternative(f.alternativeId,f.driverId?1:f.code.startsWith('impact-')?2:0);if(['choice','alternatives'].includes(f.code)){navigate('work','compare');return}if(f.code==='impact'){reviewImpact();return}if(f.code==='governance')return showGovernance();if(['driver-assumptions','requirement-assumptions'].includes(f.code)){ui.sourceFocus=f.code;navigate('work','inputs');const source=f.code==='driver-assumptions'?'driver':'requirement';document.querySelector('[data-d-source-warning="'+source+'"]')?.focus({preventScroll:true});return}editQuestion(false,['rationale','assumptions','risks','anti-pattern'].includes(f.code)?2:['links','broken-links','cited-not-linked'].includes(f.code)?1:0)}
function hideTip(){clearTimeout(tipTimer);if($('#cursor-tip'))$('#cursor-tip').hidden=true}
function showTip(el,event){if(!ui.cursor||ui.modal||matchMedia('(max-width:700px)').matches||event?.pointerType==='touch')return;clearTimeout(tipTimer);tipTimer=setTimeout(()=>{const key=el.dataset.dInsight,c=contextRecord(key);if(!c)return;const kind=key.split(':')[0],d=decision(),a=kind==='alternative'?c:option(),g=decisionGuidance(project,d,a,ui.tab),q=kind==='driver'?criterion(project,d,c.id):null;const tip=$('#cursor-tip');if(!tip)return;tip.className='r-cursor-tip d-cursor-tip';tip.innerHTML=`<small>CHAPTER 03 / ${esc(ui.tab.toUpperCase())} · ${esc(c.id||'GHOST')}</small><h3>${esc(c.title)}</h3><p>${esc(kind==='alternative'?g.explanation:q?q.measure:c.description)}</p><p class="r-tip-attention">${esc(kind==='alternative'?'Consequence: '+g.consequence:kind==='driver'?a?.assessments[c.id]?.reason||'Compare this driver across the alternatives.':'This object is affected by '+d.id+'. '+(a?.consequences||''))}</p><small>${esc(g.next)} Select for context and editable draft suggestions.</small>`;tip.innerHTML+=`<small>${esc(evidenceCursorText(project,kind==='alternative'?d?.id:c.id))}</small>`;tip.hidden=false;Promise.resolve().then(()=>{const extra=hoverTipHTML(project,c.id,3);if(extra&&!tip.hidden&&!tip.querySelector('.tip-brain'))tip.insertAdjacentHTML('beforeend',extra)}).catch(e=>console.warn('Sol’s reading for this tip could not load.',e?.message));const r=el.getBoundingClientRect(),x=event?.clientX??r.left+r.width/2,y=event?.clientY??r.top+r.height/2;tip.style.left=Math.max(8,Math.min(innerWidth-348,x+14))+'px';tip.style.top=Math.max(8,Math.min(innerHeight-tip.offsetHeight-8,y+14))+'px'},300)}
async function onClick(e){sync();
  const b=e.target.closest('button');if(!b||b.disabled||ui.busy)return;
 if(b.dataset.dComparisonView){ui.comparisonView=b.dataset.dComparisonView;render();return}
 if(b.dataset.dStage){ui.stage=b.dataset.dStage;ui.node=null;render();return}
 if(b.dataset.dSelect)return selectDecision(b.dataset.dSelect,b.dataset.stage);
 if(b.dataset.dStep!==undefined)return step(Number(b.dataset.dStep),{check:true});
 if(b.dataset.dEditOption)return editAlternative(b.dataset.dEditOption,Number(b.dataset.step||0));
 if(b.dataset.dSuggest)return useSuggestion(b.dataset.dSuggest,b.dataset.driver,Number(b.dataset.index||0));
 if(b.dataset.dChoose){if(await send('choose',{id:decision()?.id,alternativeId:b.dataset.dChoose},'Working choice saved. Record the rationale before acceptance.')){ui.alternative=b.dataset.dChoose;render()}return}
 if(b.dataset.dPreview){ui.alternative=b.dataset.dPreview;ui.proposal=null;navigate('model');return}
 if(b.dataset.dNode)return selectNode(b.dataset.dNode);
 if(b.dataset.dPattern)return previewPattern(b.dataset.dPattern);
 if(b.dataset.dFilter){ui.filter=b.dataset.dFilter;ui.filterChosen=true;render();return}
 if(b.dataset.dFix)return fix(b.dataset.dFix);
 if(b.dataset.dConflict)return editConflict(b.dataset.dConflict);
 if(b.dataset.dRemoveRel!==undefined){const rows=collectRelationships();rows.splice(Number(b.dataset.dRemoveRel),1);$('#d-relationship-rows').innerHTML=relationshipRows(rows);ui.dirty=true;return}
 switch(b.dataset.dAction){
  case'sol':assistant('sol');break;case'mind':assistant('mind');break;
  case'lifecycle-retire':{const id=b.dataset.lifecycleId;ui.retiring=[id];dialog('Retire '+id,`<p>${esc(RETIRE_TEXT)}</p><form id="record-retire-form">${recordField('record.retire','reason','')}<div class="l-dialog-actions">${dbtn('close-dialog','Cancel')}<button class="btn primary" type="submit">Retire</button></div></form>`,'retire');break;}
  case'lifecycle-restore':await send('record.restore',{ids:[b.dataset.lifecycleId],chapter:3},'Restored as it was.');break;
  case'next':next();break;case'show-all':showAllOf(b.dataset.list);render();break;
  case'new-question':editQuestion(true);break;case'go-compare':navigate('work','compare');break;case'edit-links':editQuestion(false,1);break;case'edit-rationale':editQuestion(false,decision()?.owner?2:0);break;case'edit-question':editQuestion(false,ui.stage==='record'?2:0);break;case'new-alternative':editAlternative();break;
  case'review-inputs':await send('intake',{},'Current requirements and architectural drivers reviewed.');break;
  case'next-step':step(ui.step+1,{check:true});break;case'add-relationship':{const rows=collectRelationships();if(rows.length>=12){toast('This prototype supports 12 relationships per alternative.');break}rows.push({from:'',to:'',label:''});$('#d-relationship-rows').innerHTML=relationshipRows(rows);ui.dirty=true;break}
  case'record':await send('record',{id:decision()?.id},'Decision recorded. Architect acceptance and governance remain separate.');break;
  case'accept':showAcceptance();break;case'apply-impact':showApply();break;case'governance':showGovernance();break;
  case'new-conflict':if(project.decisions.records.length<2){toast('Create a second decision before recording a conflict.');break}editConflict();break;
  case'supersede':dialog('Supersede '+ui.selected,`<form id="d-supersede-form"><p>The record and history will remain available. Its current model impact will become inactive.</p>${recordField('decision.supersede','reason','')}<div class="l-dialog-actions">${dbtn('close','Keep decision')}<button type="submit" class="btn danger">Supersede decision</button></div></form>`,'supersede');break;
  case'compare-view':navigate('work','compare');break;case'record-view':navigate('work','record');break;case'model':reviewImpact();break;case'validate':navigate('validate');break;
  case'run-checks':ui.tab='validate';await send('review',{},'Checks recorded for what is saved now.');break;
  case'edit-proposal':editAlternative(ui.proposal.existingId,0,ui.proposal);break;case'dismiss-proposal':ui.proposal=null;render();toast('Proposal dismissed. The saved model is unchanged.');break;
  case'inspect-alternative':ui.node=null;render();break;case'back':$('#workspace .stage')?.scrollIntoView({block:'start'});break;
  case'export-md':download(true);break;case'export-json':download(false);break;case'handoff':handoff();break;
  case'close':closeDialog();break;case'keep':$('#d-discard').hidden=true;break;case'discard':closeDialog(true);break;
  case'refresh':try{project=(await store.load()).document;(()=>{const message=$('#d-form-error')||$('#d-page-error');message.hidden=false;message.textContent='Latest project loaded. Your form values are preserved. Review them before saving again.'})()}catch(e){toast(e.message)}break;
  case'retry-submit':$('.d-dialog form, .r-dialog form')?.requestSubmit();break;
 }
}
async function onSubmit(e){sync();if(!e.target.closest('.d-dialog'))return;e.preventDefault();const form=e.target;if(!validateForm(form))return;const fd=new FormData(form),raw=Object.fromEntries(fd);if(form.id==='record-retire-form'){if(await send('record.retire',{ids:ui.retiring||[],reason:raw.reason,chapter:3},'Retired with your reason. You can restore it.'))ui.selected=null;render();return;}
 if(form.id==='d-question-form'){Object.assign(raw,{id:formState.id,requirementIds:fd.getAll('requirementIds'),requirementGroupIds:fd.getAll('requirementGroupIds'),driverIds:fd.getAll('driverIds'),assumptionIds:fd.getAll('assumptionIds'),stakeholderIds:fd.getAll('stakeholderIds'),dependsOn:fd.getAll('dependsOn'),assumptionsResolved:form.elements.assumptionsResolved.checked});if(await send('save',raw,'Working revision saved with its stable ADR reference.')){if(!formState.id)ui.stage='compare';render()}}
 if(form.id==='d-alternative-form'){raw.id=formState.id;raw.alternativeId=formState.alternativeId;raw.responsibilityIds=fd.getAll('responsibilityIds');raw.componentIds=fd.getAll('componentIds');raw.relationships=collectRelationships().filter(r=>r.from||r.to||r.label.trim());raw.assessments=Object.fromEntries(decision().driverIds.map(id=>[id,{effect:fd.get('effect:'+id),reason:fd.get('reason:'+id),evidence:fd.get('evidence:'+id)}]));await send('alternative',raw,'Alternative saved. Review the working choice against the updated comparison.')}
 if(form.id==='d-accept-form')await send('accept',{id:decision()?.id,acknowledge:form.elements.acknowledge?.checked===true},'Architect acceptance recorded. Governance approval remains separate.');
 if(form.id==='d-apply-form')await send('apply-impact',formState,'Reviewed model relationships applied to the current decision.');
 if(form.id==='d-governance-form')await send('governance',{id:decision()?.id,...raw},'External governance review evidence recorded.');
 if(form.id==='d-conflict-form')await send('conflict',{...raw,conflictId:formState.conflictId,decisionIds:[raw.decision0,raw.decision1]},'Decision conflict review saved.');
 if(form.id==='d-supersede-form')await send('supersede',{id:decision()?.id,reason:raw.reason},'Decision superseded; historical reasoning retained.');
 if(form.id==='d-handoff-form'&&await send('handoff',{acknowledge:form.elements.acknowledge?.checked===true},'Accepted decisions carried into the application model.'))goChapter(4);
}
function onInput(e){if(e.target.closest('.d-dialog form')){ui.dirty=true;if(e.target.name==='assumptions')e.target.form.elements.assumptionsResolved.checked=false}}
function onChange(e){if(e.target.hasAttribute('data-d-criterion')){ui.criterion=e.target.value;render();return}if(e.target.id==='d-question-select')selectDecision(e.target.value);if(e.target.dataset.dCompare!==undefined){const i=Number(e.target.dataset.dCompare);ui.compare[i]=e.target.value;if(ui.compare[0]===ui.compare[1])ui.compare[1-i]=decision().alternatives.find(a=>a.id!==e.target.value)?.id;render()}if(e.target.hasAttribute('data-rel-endpoint')){const checkbox=e.target.form.querySelector('input[name="responsibilityIds"][value="'+e.target.value+'"]');if(checkbox)checkbox.checked=true}}
// The Chapter 3 models edit through this studio's own editors, proposals and commands.
const page={
  focus(id){sync();if(project?.decisions.records.some(d=>d.id===id)){ui.selected=id;ui.alternative=null;bridge?.route?.()}},
  editQuestion(id){sync();if(!project.decisions.records.some(d=>d.id===id))return;ui.selected=id;editQuestion(false)},
  newQuestion:preset=>editQuestion(true,0,preset),
  editAlternative(decisionId,altId=null){sync();if(!project.decisions.records.some(d=>d.id===decisionId))return;ui.selected=decisionId;editAlternative(altId)},
  proposeAlternative(decisionId,record){sync();if(!project.decisions.records.some(d=>d.id===decisionId))return;ui.selected=decisionId;editAlternative(null,0,{existingId:null,record})},
  useSuggestion(decisionId,altId,driverId,i=0){sync();if(!project.decisions.records.some(d=>d.id===decisionId))return;ui.selected=decisionId;useSuggestion(altId,driverId,i)},
  async choose(decisionId,altId){sync();ui.selected=decisionId;if(await send('choose',{id:decisionId,alternativeId:altId},'Working choice saved. Record the rationale before acceptance.')){ui.alternative=altId;render()}},
  get proposal(){return ui.proposal?{...ui.proposal,decisionId:ui.selected}:null},get busy(){return ui.busy}
};
// A surface that cannot be drawn from the saved project (an unexpected stored value, for example) says so in place, as
// the chapter's own page did when it could not open, instead of leaving the whole workspace undrawn.
const guard=draw=>{try{return draw()}catch(e){console.warn('Chapter 3 could not draw this part of the page.',e?.message);return `<article class="r-card r-unavailable" role="status"><p class="r-kicker">Chapter 03</p><h2>This part of the chapter could not be drawn.</h2><p>${esc(e?.message||'The saved project holds a value this view does not recognise.')}</p><p class="r-note">Saved records are unchanged. Review the record in its editor or reload the page.</p></article>`}};
// Every document and window listener of this studio, on one AbortController: dispose() takes them all away.
function bind(b){
  bridge=b;settle();listeners?.abort();listeners=new AbortController();const signal=listeners.signal;
  // The canvas's drafts (rc41, W3): a decision placed on the picture opens this editor; nothing is saved until it is.
  draftRelease?.();draftRelease=registerDraftEditor(3,{element(){editQuestion(true,0,{});}});
  // The chapter's records on Output (round 26, D-26-13): a decision's row reads its revision and the choice recorded.
  registerOutputRecords(3,{detail:r=>{const d=r.object?.record;return d&&r.type==='decision'?'Revision '+d.revision+' · '+(chosen(d)?chosen(d).title:'No choice recorded'):undefined;}});
  document.addEventListener('aiw:sdd-edit',e=>{const t=e.detail;if(t?.chapter!==3||bridge?.state.chapter!==3||bridge.state.tab!=='work')return;const d=project.decisions.records.find(x=>x.id===t.ref);if(!d)return;ui.selected=d.id;syncSelection();
    if(t.editor==='decision-alternative'){const a=d.alternatives.find(x=>x.id===t.recordRef);if(a)editAlternative(a.id);else {ui.stage='compare';render();} }
    else if(t.editor==='decision-assessment'){const a=d.alternatives.find(x=>x.id===d.selectedAlternativeId)||d.alternatives[0];if(a){editAlternative(a.id,1);const driver=project.quality.drivers.find(x=>driverCode(project,x)===t.driverRef);if(driver)document.querySelector('.d-dialog [name="reason:'+driver.id+'"]')?.focus({preventScroll:true});}else {ui.stage='compare';render();} }
    else if(t.field==='alternatives'){editAlternative();}
    else if(t.field==='selectedAlternativeId'){ui.stage='compare';render();document.querySelector('.d-option .d-choice-button:not([disabled]),[data-d-action="new-alternative"]')?.focus({preventScroll:true});}
    else editQuestion(false,['rationale','impact'].includes(t.field)?2:0);
    document.querySelector('.d-dialog [name="'+t.field+'"]')?.focus({preventScroll:true});
  },{signal});
  document.addEventListener('click',onClick,{signal});document.addEventListener('submit',onSubmit,{signal});
  document.addEventListener('input',onInput,{signal});document.addEventListener('change',onChange,{signal});
  document.addEventListener('invalid',e=>{const panel=e.target.closest?.('[data-d-panel]');if(panel)step(Number(panel.dataset.dPanel))},{capture:true,signal});
  document.addEventListener('pointerover',e=>{const el=e.target.closest?.('[data-d-insight]');if(el)showTip(el,e)},{signal});
  document.addEventListener('pointerout',e=>{if(e.target.closest?.('[data-d-insight]'))hideTip()},{signal});
  document.addEventListener('focusin',e=>{const el=e.target.closest?.('[data-d-insight]');if(el)showTip(el)},{signal});
  document.addEventListener('focusout',hideTip,{signal});
  document.addEventListener('keydown',e=>{if(e.key==='Escape')hideTip()},{signal});
  window.addEventListener('beforeunload',e=>{if(ui.dirty||ui.busy){e.preventDefault();e.returnValue=''}},{signal});
  window.aiwDecisionsPage=page;
  // The chapter's own rules in decisions.css are scoped to this class, which only this studio's chapter carries.
  document.body.classList.add('decisions-app');
  // Field sparks on this studio's editors, and the Co-author panel's way into them (round 2, I2-12).
  sparkStudio({store,signal,dialog:'.d-dialog',recordId:c=>(c==='decision.alternative'?formState?.alternativeId:formState?.id)||null,editors:{'decision.save':id=>page.editQuestion(id),'decision.alternative':id=>{const d=project?.decisions.records.find(x=>x.alternatives.some(a=>a.id===id));if(d)page.editAlternative(d.id,id)}},links:c=>c==='decision.alternative'?{decisionId:formState?.id||''}:{}});
}
function dispose(){listeners?.abort();listeners=null;draftRelease?.();draftRelease=null;hideTip();closeDialog(true,{restore:false});document.body.classList.remove('decisions-app');if(window.aiwDecisionsPage===page)delete window.aiwDecisionsPage;}
return {
  get workSection(){return ui.stage},openSection(id){if(!validWorkSection(3,id))return false;ui.stage=id;ui.node=null;return true;},
  work:()=>guard(()=>{settle();return work()}),validation:()=>guard(()=>{settle();return validation()}),output:()=>guard(()=>{settle();return output()}),inspector:()=>guard(()=>{settle();return renderStudioRecordCard(project,3,ui.selected,()=>inspector(),graphOf(project))}),
  assistance:()=>guard(()=>{settle();const d=decision();return `<div id="d-page-error" class="r-error" role="alert" hidden></div><div class="r-assistant-bar"><div><span class="r-kicker">Ch. 03 / ${esc(ui.tab[0].toUpperCase()+ui.tab.slice(1))}</span><span>${d?esc(d.id+' · '+statusLabel(d)):'Project context'}</span></div>${ui.tab==='work'?'':questionPicker()}<nav aria-label="Contextual assistance">${btn('sol',icon('spark')+'Sol')}${btn('mind',icon('book')+'Co-design')}<button type="button" class="r-btn" data-action="cursor" aria-pressed="${ui.cursor}">${icon('cursor')}Hover explanations <span class="ux-toggle-state" aria-hidden="true">${ui.cursor?'On':'Off'}</span></button></nav></div>`}),
  milestones:()=>milestonesOf(doc()),graph:()=>doc()?graphOf(doc()):{nodes:[],edges:[]},
  next(){settle();next()},assistant(kind){settle();assistant(kind==='mind'?'mind':'sol')},
  tip(n){sync();const d=project?.decisions.records.find(x=>x.id===n?.id);return d?`<small>CHAPTER 03 · ${esc(d.id)}</small><h3>${esc(d.question)}</h3><p>${esc(statusLabel(d))} · ${esc(chosen(d)?.title||'No choice recorded')}</p>`:''},
  bind,dispose,get busy(){return ui.busy},get proposal(){return page.proposal}
};
}
